INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_cjp-souveti_0','Kolik vět jednoduchých obsahuje souvětí „Pršelo, a proto jsme zůstali doma.“?',ARRAY['čtyři','tři','dvě','jednu']::TEXT[],2,'Jsou to věty „Pršelo“ a „proto jsme zůstali doma“.',1,ARRAY[]::TEXT[],NULL,0,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_1','Co je souvětí?',ARRAY['jedno slovo','věta s jedním podmětem','věta bez přísudku','spojení dvou nebo více vět jednoduchých']::TEXT[],3,'Souvětí má alespoň dvě slovesa v osobním tvaru nebo dvě predikace.',1,ARRAY[]::TEXT[],NULL,1,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_2','Která spojka je slučovací?',ARRAY['protože','ale','aby','a']::TEXT[],3,'Spojka a spojuje věty stejné důležitosti.',1,ARRAY[]::TEXT[],NULL,2,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_3','Která spojka je odporovací?',ARRAY['ale','proto','nebo','a']::TEXT[],0,'Ale vyjadřuje rozpor.',2,ARRAY[]::TEXT[],NULL,3,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_4','Která spojka uvozuje vedlejší větu účelovou?',ARRAY['protože','když','ale','aby']::TEXT[],3,'Aby vyjadřuje účel.',2,ARRAY[]::TEXT[],NULL,4,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_5','Která spojka uvozuje vedlejší větu příčinnou?',ARRAY['aby','protože','když','ale']::TEXT[],1,'Protože vyjadřuje příčinu.',2,ARRAY[]::TEXT[],NULL,5,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_6','Jaký druh vedlejší věty je „Když zazvonilo, děti odešly“?',ARRAY['časová','přívlastková','příčinná','podmínková']::TEXT[],0,'Když zazvonilo = kdy? Časová věta.',3,ARRAY[]::TEXT[],NULL,6,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_7','Jaký druh vedlejší věty je v souvětí „Přišel domů, protože ho bolela hlava“?',ARRAY['příčinná','časová','přípustková','účelová']::TEXT[],0,'Protože = příčina.',3,ARRAY[]::TEXT[],NULL,7,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_8','Jaký druh vedlejší věty je „Kdo se bojí“ v souvětí „Kdo se bojí, nesmí do lesa“?',ARRAY['předmětná','podmětná','příslovečná','přívlastková']::TEXT[],1,'Ptáme se kdo nesmí do lesa? Ten, kdo se bojí.',3,ARRAY[]::TEXT[],NULL,8,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_9','Jaký druh vedlejší věty je v souvětí „Řekl, že přijde zítra“?',ARRAY['přívlastková','podmětná','předmětná','časová']::TEXT[],2,'Řekl co? Že přijde zítra.',4,ARRAY[]::TEXT[],NULL,9,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_10','Jaký druh vedlejší věty je v souvětí „Kniha, kterou čtu, je zajímavá“?',ARRAY['přívlastková','časová','předmětná','podmínková']::TEXT[],0,'Jaká kniha? Kterou čtu.',4,ARRAY[]::TEXT[],NULL,10,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_11','Jaký druh vedlejší věty je v souvětí „Kdyby pršelo, nepůjdeme ven“?',ARRAY['podmínková','časová','příčinná','účelová']::TEXT[],0,'Kdyby = podmínka.',4,ARRAY[]::TEXT[],NULL,11,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_12','Jaký druh vedlejší věty je v souvětí „Ačkoli pršelo, šli jsme ven“?',ARRAY['příčinná','přípustková','podmínková','účelová']::TEXT[],1,'Ačkoli vyjadřuje přípustku, tedy děj navzdory překážce.',5,ARRAY[]::TEXT[],NULL,12,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_13','Jak se nazývá souvětí, jehož věty jsou stejně důležité a jsou spojeny např. spojkami a, ale?',ARRAY['souvětí souřadné','souvětí podřadné','věta jednočlenná','věta dvojčlenná']::TEXT[],0,'V souřadném souvětí jsou věty na sobě nezávislé.',5,ARRAY[]::TEXT[],NULL,13,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_14','Kolik vět obsahuje souvětí „Vím, že přijdeš, ale nevím kdy.“?',ARRAY['čtyři','tři','dvě','pět']::TEXT[],0,'Vím / že přijdeš / ale nevím / kdy.',5,ARRAY[]::TEXT[],NULL,14,'c_cjp-souveti',NULL,NOW()),
('q_cjp-frazeologie_0','Co znamená rčení „lhát jako když tiskne“?',ARRAY['mluvit potichu','tisknout noviny','být zticha','velmi hodně lhát']::TEXT[],3,'Znamená to lhát často a ve velkém.',1,ARRAY[]::TEXT[],NULL,0,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_1','Co znamená rčení „být jako pěst na oko“?',ARRAY['vůbec se k sobě nehodit','prát se','být velmi silný','mít modřinu']::TEXT[],0,'Znamená to, že věci nebo lidé k sobě vůbec nesedí.',1,ARRAY[]::TEXT[],NULL,1,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_2','Co znamená rčení „mít máslo na hlavě“?',ARRAY['mít na svědomí nějakou vinu','být štědrý','být tlustý','vařit']::TEXT[],0,'Kdo má máslo na hlavě, není bez viny.',1,ARRAY[]::TEXT[],NULL,2,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_3','Dokonči přísloví: Řemeslo má …',ARRAY['tvrdý chleba','pevné stěny','zlaté dno','stříbrné dno']::TEXT[],2,'Řemeslo má zlaté dno.',2,ARRAY[]::TEXT[],NULL,3,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_4','Dokonči přísloví: Kdo jinému jámu kopá, …',ARRAY['dostane lopatu','je dobrý zahradník','bude bohatý','sám do ní padá']::TEXT[],3,'Kdo jinému jámu kopá, sám do ní padá.',2,ARRAY[]::TEXT[],NULL,4,'c_cjp-frazeologie',NULL,NOW()),
