('q_cjp-frazeologie_6','Co znamená rčení „hodit flintu do žita“?',ARRAY['vystřelit','zasít obilí','vzdát se','ztratit zbraň']::TEXT[],2,'Znamená to vzdát se dřív, než je to nutné.',3,ARRAY[]::TEXT[],NULL,6,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_7','Co znamená rčení „kupovat zajíce v pytli“?',ARRAY['lovit','nakupovat zdarma','být chytrý','koupit něco, co dopředu neznám']::TEXT[],3,'Kupuje se věc bez možnosti ji předem prohlédnout.',3,ARRAY[]::TEXT[],NULL,7,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_8','Co znamená rčení „chodit kolem horké kaše“?',ARRAY['vařit','spěchat','vyhýbat se podstatě věci','být hladový']::TEXT[],2,'Kdo chodí kolem horké kaše, nemluví přímo.',3,ARRAY[]::TEXT[],NULL,8,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_9','Co znamená rčení „vzít nohy na ramena“?',ARRAY['rychle utéct','být unavený','nést zavazadlo','být zraněný']::TEXT[],0,'Znamená to rychle uprchnout.',4,ARRAY[]::TEXT[],NULL,9,'c_cjp-frazeologie',NULL,NOW()),
